        # Keep the demo catalog deterministic. Existing products that are not part of
        # this catalog are removed only when they have never been used in an order.
        Product.objects.filter(order_items__isnull=True).delete()

        created = 0
        for category_name, products in catalog.items():
            category, _ = Category.objects.get_or_create(
                name=category_name,
                defaults={"description": f"Curated {category_name.lower()} for modern lifestyles."},
            )
            for name, description, price, stock, rating, image_name in products:
                product, was_created = Product.objects.update_or_create(
                    name=name,
                    defaults={
                        "category": category,
                        "description": description,
                        "price": Decimal(price),
                        "stock": stock,
                        "rating": Decimal(str(rating)),
                        "image": image_name,
                    },
                )
                created += int(was_created)

        total = Product.objects.count()
        self.stdout.write(self.style.SUCCESS(f"Nawab catalog ready: {total} products across {len(catalog)} categories. New products created: {created}."))
